def run(shop_url, claim_focus, home_status, home_title, home_text, home_error, search_results):
    def norm(x):
        return ' '.join((x or '').split()).lower() if isinstance(x, str) else ''

    title = norm(home_title)
    text = norm(home_text)
    combined = title + ' ' + text
    search_blob = ''
    sources = []

    if isinstance(search_results, list):
        for r in search_results[:5]:
            if isinstance(r, dict):
                t = (r.get('title') or '').strip()
                c = (r.get('content') or '').strip()
                u = (r.get('url') or '').strip()
                if t or c or u:
                    sources.append({'title': t[:120], 'url': u[:300]})
                    search_blob += ' ' + norm(t) + ' ' + norm(c)

    all_text = combined + ' ' + search_blob
    red_flags = []
    positive_signals = []

    def add(item, arr):
        if item not in arr:
            arr.append(item)

    try:
        hs = int(home_status or 0)
    except Exception:
        hs = 0

    if hs == 0:
        add('site unreachable or fetch failed', red_flags)
    if any(k in all_text for k in ['no refund', 'refunds are not accepted', 'all sales final']):
        add('refund policy looks harsh or missing refunds', red_flags)
    if any(k in all_text for k in ['contact us', 'email', 'phone', 'address', 'support']):
        add('some contact details are visible', positive_signals)
    else:
        add('no clear contact details found', red_flags)
    if any(k in all_text for k in ['secure checkout', 'visa', 'mastercard', 'paypal', 'ssl']):
        add('normal payment or security signals present', positive_signals)
    if any(k in all_text for k in ['too good to be true', '90% off', '99% off', 'limited time only', 'act now', 'free today']):
        add('aggressive or unrealistic marketing', red_flags)
    if any(k in all_text for k in ['clone', 'copied', 'same as', 'template', 'generic']):
        add('site content looks generic or copied', red_flags)
    if any(k in all_text for k in ['company registration', 'vat', 'terms and conditions', 'privacy policy']):
        add('basic legal pages are present', positive_signals)
    if any(k in search_blob for k in ['scam', 'fraud', 'complaint', 'never received', 'chargeback', 'fake', 'warning']):
        add('public complaints or scam warnings appear in search results', red_flags)
    if any(k in search_blob for k in ['trusted', 'legit', 'positive reviews', 'delivered', 'refund worked']):
        add('some public trust signals appear in search results', positive_signals)

    score = 0
    if 'site unreachable or fetch failed' in red_flags:
        score += 30
    if 'no clear contact details found' in red_flags:
        score += 20
    if 'refund policy looks harsh or missing refunds' in red_flags:
        score += 20
    if 'public complaints or scam warnings appear in search results' in red_flags:
        score += 20
    if 'site content looks generic or copied' in red_flags:
        score += 10
    if 'some contact details are visible' in positive_signals:
        score -= 10
    if 'basic legal pages are present' in positive_signals:
        score -= 10
    if 'normal payment or security signals present' in positive_signals:
        score -= 10
    if 'some public trust signals appear in search results' in positive_signals:
        score -= 10

    if score < 0:
        score = 0
    if score > 100:
        score = 100

    if score >= 70:
        verdict = 'high risk'
    elif score >= 40:
        verdict = 'medium risk'
    else:
        verdict = 'lower risk'

    reasons = []
    if claim_focus:
        reasons.append(f'Focus checked: {claim_focus}')
    if red_flags:
        reasons.extend(red_flags[:4])
    if not reasons:
        reasons = ['No strong signals found either way.']

    return {
        'score': score,
        'verdict': verdict,
        'reasons': reasons,
        'red_flags': red_flags,
        'positive_signals': positive_signals,
        'sources': sources[:5],
        'home_status': hs,
        'home_error': home_error or ''
    }

def run(shop_url, claim_focus, score, verdict, reasons, red_flags, positive_signals, sources, home_status, home_error):
    shop = shop_url or 'the shop'
    focus = claim_focus or 'the requested focus'
    reasons = reasons or []
    red_flags = red_flags or []
    positive_signals = positive_signals or []
    sources = sources or []

    if verdict == 'high risk':
        opener = 'High risk.'
    elif verdict == 'medium risk':
        opener = 'Medium risk.'
    else:
        opener = 'Lower risk.'

    if score >= 70:
        score_text = f'Risk score: {score}/100.'
    elif score >= 40:
        score_text = f'Risk score: {score}/100.'
    else:
        score_text = f'Risk score: {score}/100.'

    reason_text = '; '.join(reasons[:3]) if reasons else 'No clear evidence either way.'
    speech = f'{opener} {shop}. {score_text} Main reasons: {reason_text}.'
    speech = speech[:900]

    def bullet_list(items):
        if not items:
            return '- None'
        return '\n'.join(f'- {x}' for x in items[:8])

    src_lines = []
    for s in sources[:5]:
        if isinstance(s, dict):
            title = s.get('title') or 'source'
            url = s.get('url') or ''
            src_lines.append(f'- {title}' + (f' — {url}' if url else ''))
    if not src_lines:
        src_lines = ['- None']

    report = f'''# Scam Check Report

## Verdict
- **Shop:** {shop}
- **Focus:** {focus}
- **Risk score:** {score}/100
- **Verdict:** {verdict}
- **Homepage status:** {home_status}
- **Homepage error:** {home_error or 'none'}

## Reasons
{bullet_list(reasons)}

## Red flags
{bullet_list(red_flags)}

## Positive signals
{bullet_list(positive_signals)}

## Sources checked
{chr(10).join(src_lines)}
'''
    return {'speech': speech, 'report': report}
